indirect enum Node {
    case lit(Int)
    case binary(Node, String, Node)

    var children: [Node] {
        switch self {
        case .lit: return []
        case .binary(let l, _, let r): return [l, r]
        }
    }
}

func walk(_ n: Node, _ visit: (Node) -> Void) {
    visit(n)
    n.children.forEach { walk($0, visit) }
}
